-- Generated by Ingestron from transforms/daily_sales.yaml (table daily_sales). Do not edit: change the definitions and generate again.
CREATE OR REFRESH MATERIALIZED VIEW `silver`.`daily_sales` (
  CONSTRAINT `email_not_null` EXPECT (`email` IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT `day_not_null` EXPECT (`day` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Order totals per customer and day.'
CLUSTER BY AUTO
AS
SELECT
  c.email,
  DATE(o.ordered_at) AS day,
  SUM(o.total) AS total
FROM `bronze`.`orders` AS o
JOIN `bronze`.`customers` AS c ON c.id = o.customer_id
GROUP BY c.email, DATE(o.ordered_at);
